export function formatPythonValue(value) {
  if (value === null || value === undefined) {
    return "None";
  }

  if (value === true) {
    return "True";
  }

  if (value === false) {
    return "False";
  }

  return String(value);
}

export function writePythonLines(values, stream = process.stdout) {
  const rendered = values.map((value) => formatPythonValue(value)).join("\n");
  stream.write(`${rendered}\n`);
}

