import { SchemaError } from "../errors.mjs";
import {
  hasUniqueItems,
  isNonNegativeInteger,
  isNumber,
  isObjectInstance,
  isSchemaLike,
  isStringArray,
  isValidTypeName,
} from "./utils.mjs";

function ensure(condition, message, schemaPath) {
  if (!condition) {
    throw new SchemaError(message, { schemaPath });
  }
}

function validateStringArray(value, schemaPath) {
  ensure(isStringArray(value), "expected an array of strings", schemaPath);
  ensure(hasUniqueItems(value), "expected unique strings", schemaPath);
}

function validateSchemaContainer(container, schemaPath) {
  if (!isObjectInstance(container)) {
    throw new SchemaError("expected an object containing schemas", {
      schemaPath,
    });
  }

  for (const [key, schema] of Object.entries(container)) {
    validateDraft7Schema(schema, [...schemaPath, key]);
  }
}

export function validateDraft7Schema(schema, schemaPath = []) {
  if (typeof schema === "boolean") {
    return;
  }

  ensure(
    isObjectInstance(schema),
    "expected schema to be an object or boolean",
    schemaPath
  );

  for (const [keyword, value] of Object.entries(schema)) {
    switch (keyword) {
      case "$ref":
      case "$id":
      case "title":
      case "description":
      case "default":
      case "format":
      case "contentMediaType":
      case "contentEncoding":
        ensure(typeof value === "string", "expected a string", [
          ...schemaPath,
          keyword,
        ]);
        break;

      case "type":
        if (typeof value === "string") {
          ensure(isValidTypeName(value), "expected a valid type name", [
            ...schemaPath,
            keyword,
          ]);
        } else {
          ensure(Array.isArray(value) && value.length > 0, "expected a non-empty array", [
            ...schemaPath,
            keyword,
          ]);
          validateStringArray(value, [...schemaPath, keyword]);
          ensure(
            value.every((item) => isValidTypeName(item)),
            "expected valid type names",
            [...schemaPath, keyword]
          );
        }
        break;

      case "properties":
      case "patternProperties":
      case "definitions":
        validateSchemaContainer(value, [...schemaPath, keyword]);
        break;

      case "required":
        validateStringArray(value, [...schemaPath, keyword]);
        break;

      case "enum":
        ensure(Array.isArray(value), "expected an array", [...schemaPath, keyword]);
        break;

      case "const":
        break;

      case "items":
        if (Array.isArray(value)) {
          for (let index = 0; index < value.length; index += 1) {
            validateDraft7Schema(value[index], [...schemaPath, keyword, index]);
          }
        } else {
          validateDraft7Schema(value, [...schemaPath, keyword]);
        }
        break;

      case "additionalItems":
      case "additionalProperties":
      case "contains":
      case "propertyNames":
      case "if":
      case "then":
      case "else":
      case "not":
        validateDraft7Schema(value, [...schemaPath, keyword]);
        break;

      case "allOf":
      case "anyOf":
      case "oneOf":
        ensure(Array.isArray(value) && value.length > 0, "expected a non-empty array", [
          ...schemaPath,
          keyword,
        ]);

        for (let index = 0; index < value.length; index += 1) {
          validateDraft7Schema(value[index], [...schemaPath, keyword, index]);
        }
        break;

      case "dependencies":
      case "dependentRequired":
        ensure(isObjectInstance(value), "expected an object", [
          ...schemaPath,
          keyword,
        ]);

        for (const [property, dependency] of Object.entries(value)) {
          if (Array.isArray(dependency)) {
            validateStringArray(dependency, [...schemaPath, keyword, property]);
          } else {
            validateDraft7Schema(dependency, [...schemaPath, keyword, property]);
          }
        }
        break;

      case "minimum":
      case "maximum":
      case "exclusiveMinimum":
      case "exclusiveMaximum":
        ensure(isNumber(value), "expected a number", [...schemaPath, keyword]);
        break;

      case "multipleOf":
        ensure(isNumber(value) && value > 0, "expected a positive number", [
          ...schemaPath,
          keyword,
        ]);
        break;

      case "minItems":
      case "maxItems":
      case "minLength":
      case "maxLength":
      case "minProperties":
      case "maxProperties":
        ensure(isNonNegativeInteger(value), "expected a non-negative integer", [
          ...schemaPath,
          keyword,
        ]);
        break;

      case "pattern":
        ensure(typeof value === "string", "expected a string", [
          ...schemaPath,
          keyword,
        ]);
        break;

      case "uniqueItems":
        ensure(typeof value === "boolean", "expected a boolean", [
          ...schemaPath,
          keyword,
        ]);
        break;

      default:
        break;
    }
  }
}

export function checkDraft7Schema(schema) {
  validateDraft7Schema(schema);
  return null;
}

