class ErrorTreeNode {
  constructor() {
    this.errors = new Map();
    this.children = new Map();
  }

  addError(error) {
    let node = this;

    for (const segment of error.path) {
      if (!node.children.has(segment)) {
        node.children.set(segment, new ErrorTreeNode());
      }

      node = node.children.get(segment);
    }

    const key = error.validator ?? "__unknown__";
    node.errors.set(key, error);
  }

  get total_errors() {
    let total = this.errors.size;

    for (const child of this.children.values()) {
      total += child.total_errors;
    }

    return total;
  }
}

export class ValidationError extends Error {
  constructor(message, options = {}) {
    super(message);
    this.name = "ValidationError";
    this.path = Array.isArray(options.path) ? [...options.path] : [];
    this.schemaPath = Array.isArray(options.schemaPath)
      ? [...options.schemaPath]
      : [];
    this.validator = options.validator ?? null;
    this.validatorValue = options.validatorValue;
    this.instance = options.instance;
    this.schema = options.schema;
    this.context = Array.isArray(options.context) ? options.context : [];
  }
}

export class SchemaError extends Error {
  constructor(message, options = {}) {
    super(message);
    this.name = "SchemaError";
    this.schemaPath = Array.isArray(options.schemaPath)
      ? [...options.schemaPath]
      : [];
  }
}

export class ErrorTree {
  constructor(errors = []) {
    this._root = new ErrorTreeNode();

    for (const error of errors) {
      this._root.addError(error);
    }
  }

  get total_errors() {
    return this._root.total_errors;
  }
}

