export function hasUniqueItems(value) {
  return new Set(value).size === value.length;
}

export function isValidTypeName(value) {
  return (
    value === "null" ||
    value === "boolean" ||
    value === "object" ||
    value === "array" ||
    value === "number" ||
    value === "integer" ||
    value === "string"
  );
}

export function matchesType(typeName, value) {
  switch (typeName) {
    case "null":
      return value === null;
    case "boolean":
      return typeof value === "boolean";
    case "object":
      return isObjectInstance(value);
    case "array":
      return Array.isArray(value);
    case "number":
      return isNumber(value);
    case "integer":
      return isNumber(value) && Number.isInteger(value);
    case "string":
      return typeof value === "string";
    default:
      return false;
  }
