}

export function isMultipleOf(instance, divisor) {
  if (!isNumber(instance) || !isNumber(divisor) || divisor === 0) {
    return false;
  }

  const quotient = instance / divisor;
  const rounded = Math.round(quotient);
  return Math.abs(quotient - rounded) <= 1e-12;
