const programName = getProgramName(process.argv[1]);
emitDeprecationWarning();

const parsedArgs = parseArgs(process.argv.slice(2));

if (parsedArgs.kind === "help") {
  process.stdout.write(formatHelp(programName));
  process.exit(0);
}

if (parsedArgs.kind === "error") {
  process.stderr.write(formatCliError(programName, parsedArgs.message));
  process.exit(2);
}

const instance = JSON.parse(parsedArgs.values.a);
const schema = JSON.parse(parsedArgs.values.b);

const validator = new Draft7Validator(schema);

const errors = Array.from(validator.iter_errors(instance));
const tree = new ErrorTree(errors);

const total = tree.total_errors;
const firstPass = Array.from(validator.iter_errors(instance));
const secondPass = Array.from(validator.iter_errors(instance));

const check1 = validator.is_valid(instance);
const check2 = validator.is_valid(instance);
const check3 = validator.is_valid(instance);

const schemaCheck1 = validator.check_schema(schema);
const schemaCheck2 = validator.check_schema(schema);

const tree1 = new ErrorTree(firstPass);
const tree2 = new ErrorTree(secondPass);

writePythonLines([
  total,
  firstPass.length,
  secondPass.length,
  check1,
  check2,
  check3,
  schemaCheck1,
  schemaCheck2,
  tree1.total_errors,
  tree2.total_errors,
]);
